// Build-time access to apps/web/src/data/cities.json (generated by `pnpm cities:build`).
// validateData() is the quality gate: the build fails instead of publishing a thin or broken page.
import raw from '../data/cities.json';
import { dupeNames, type CityRec, type ZoneTable } from './city-facts';

export interface CityData {
  source: string;
  tzdata: string | null;
  first_year: number;
  countries: Record<string, string>;
  zones: Record<string, ZoneTable>;
  cities: CityRec[];
}

export const DATA = raw as unknown as CityData;
export const dupes = dupeNames(DATA.cities);

/** Country code -> its cities, largest first. */
export const citiesByCountry = new Map<string, CityRec[]>();
for (const c of [...DATA.cities].sort((a, b) => b.population - a.population || a.slug.localeCompare(b.slug))) {
  const list = citiesByCountry.get(c.country_code) ?? [];
  list.push(c);
  citiesByCountry.set(c.country_code, list);
}

let checked = false;
export function validateData(): void {
  if (checked) return;
  const problems: string[] = [];
  const slugs = new Set<string>();
  for (const c of DATA.cities) {
    const where = `city "${c.slug}"`;
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(c.slug)) problems.push(`${where}: bad slug`);
    if (slugs.has(c.slug)) problems.push(`${where}: duplicate slug`);
    slugs.add(c.slug);
    if (!c.name.trim()) problems.push(`${where}: no name`);
    if (!DATA.countries[c.country_code]) problems.push(`${where}: unknown country ${c.country_code}`);
    if (!DATA.zones[c.zone] || Object.keys(DATA.zones[c.zone] ?? {}).length < 2) problems.push(`${where}: no zone data for ${c.zone}`);
    if (!Number.isFinite(c.lat) || !Number.isFinite(c.lon) || Math.abs(c.lat) > 90 || Math.abs(c.lon) > 180) problems.push(`${where}: bad coordinates`);
    if (!(c.population >= 0)) problems.push(`${where}: bad population`);
  }
  if (DATA.cities.length < 1000) problems.push(`only ${DATA.cities.length} cities; run pnpm cities:build`);
  const thisYear = new Date().getUTCFullYear();
  if (DATA.first_year + 1 < thisYear) problems.push(`zone data starts in ${DATA.first_year}; rerun pnpm cities:build for ${thisYear}`);
  if (problems.length) throw new Error(`cities.json failed the quality gate:\n - ${problems.slice(0, 30).join('\n - ')}`);
  checked = true;
}
